fn lookupCategory(name: []const u8) ?Category {
    return PROPERTY_MAP.get(name);
}

/// Returns the category name after stripping a "General_Category=" prefix,
/// or just returns the original name.
fn extractPropertyName(name: []const u8) []const u8 {
    if (std.mem.indexOf(u8, name, "=")) |eq_pos| {
        return name[eq_pos + 1 ..];
    }
    return name;
}

/// Resolve a Unicode property name to a list of character ranges.
/// Returns null if the property is unknown.
pub fn getRanges(allocator: std.mem.Allocator, raw_name: []const u8) !?[]const Range {
    const name = extractPropertyName(raw_name);
    const cat = lookupCategory(name) orelse return null;
    return @as(?[]const Range, try getCategoryRanges(allocator, cat));
}

